import java.util.concurrent.atomic.AtomicReference

final class AccountStore(val state: AtomicReference[Map[String, Long]]):
  def transfer(from: String, to: String, amt: Long): Boolean = {
    @tailrec
    def loop(): Boolean = {
      val cur = state.get()                       // immutable: retry is free, ABA impossible
      if (cur.getOrElse(from, 0L) < amt) false
      else {
        val next = cur.updated(from, cur(from) - amt)
                       .updated(to, cur.getOrElse(to, 0L) + amt)
        if (state.compareAndSet(cur, next)) true else loop()   // retry on lost race
      }
    }
    loop()                                        // @tailrec keeps this O(1) stack
  }
